\set ON_ERROR_STOP on
begin;
insert into auth.users values
 ('00000000-0000-4000-8000-000000000001'),
 ('00000000-0000-4000-8000-000000000002'),
 ('00000000-0000-4000-8000-000000000003'),
 ('00000000-0000-4000-8000-000000000004');

create function pg_temp.assert_true(ok boolean, description text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'FAILED: %', description; end if; end $$;
create function pg_temp.expect_failure(command text, description text) returns void language plpgsql as $$
declare failed boolean := false;
begin
  begin execute command; exception when others then failed := true; end;
  if not failed then raise exception 'FAILED (unexpected success): %', description; end if;
end $$;

set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
insert into public.contests(id,host_id,title,ends_at,fields) values (
 '10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','발표 대회',clock_timestamp()+interval '1 hour',
 '[{"id":"20000000-0000-4000-8000-000000000001","type":"file","label":"발표 자료","description":"PPT만","required":true,"extensions":".ppt,.pptx","max_size_mb":1},
   {"id":"20000000-0000-4000-8000-000000000002","type":"link","label":"영상","description":"","required":true},
   {"id":"20000000-0000-4000-8000-000000000003","type":"text","label":"소개","description":"","required":true},
   {"id":"20000000-0000-4000-8000-000000000004","type":"file","label":"보고서","description":"PDF만","required":false,"extensions":".pdf","max_size_mb":2}]');
select pg_temp.assert_true(abs(extract(epoch from(public.contest_server_time()-clock_timestamp()))) < 1,'RPC uses server clock');
select pg_temp.expect_failure($q$insert into public.contests(host_id,title,fields) values ('00000000-0000-4000-8000-000000000002','fake','[]')$q$, 'cannot forge host');
select pg_temp.expect_failure($q$update public.contests set fields='[]'$q$, 'host cannot change fields');

-- Participant uploads a valid PowerPoint file.
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
insert into storage.objects(bucket_id,name,metadata) values
 ('contest-submissions','10000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000001/upload.PPTX','{"size":123}');
select pg_temp.expect_failure($q$insert into storage.objects(bucket_id,name,metadata) values ('contest-submissions','10000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000001/upload.exe','{"size":123}')$q$,'upload rejects wrong extension');
select pg_temp.expect_failure($q$insert into storage.objects(bucket_id,name,metadata) values ('contest-submissions','10000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000004/report.pptx','{"size":123}')$q$,'extension restrictions differ per field');
select pg_temp.expect_failure($q$insert into public.contest_submissions(contest_id,user_id,participant_name,answers) values ('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002','참가자','{}')$q$,'rejects missing required answers');
insert into public.contest_submissions(contest_id,user_id,participant_name,answers) values (
 '10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002','참가자',
 '{"20000000-0000-4000-8000-000000000001":{"path":"10000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000001/upload.PPTX","name":"발표.PPTX","size":123},"20000000-0000-4000-8000-000000000002":"https://example.com/video","20000000-0000-4000-8000-000000000003":"작품 소개"}');
-- Simulate the full conflict-key UPDATE generated by PostgREST upsert.
insert into public.contest_submissions(contest_id,user_id,participant_name,answers)
 select contest_id,user_id,'수정한 참가자',answers from public.contest_submissions
 on conflict(contest_id,user_id) do update set contest_id=excluded.contest_id,user_id=excluded.user_id,participant_name=excluded.participant_name,answers=excluded.answers;
select pg_temp.assert_true((select count(*)=1 and max(participant_name)='수정한 참가자' from public.contest_submissions),'one submission per participant, resubmit works');
select pg_temp.expect_failure($q$update public.contest_submissions set answers=jsonb_set(answers,'{20000000-0000-4000-8000-000000000002}','"javascript:alert(1)"')$q$,'rejects unsafe URLs');
select pg_temp.expect_failure($q$update public.contest_submissions set answers=jsonb_set(answers,'{20000000-0000-4000-8000-000000000001,size}','1048577')$q$,'rejects oversized file');
select pg_temp.expect_failure($q$update public.contest_submissions set answers=jsonb_set(answers,'{20000000-0000-4000-8000-000000000001,size}','124')$q$,'rejects forged file metadata');
select pg_temp.expect_failure($q$update public.contest_submissions set answers=jsonb_set(answers,'{20000000-0000-4000-8000-000000000001,name}','"renamed.exe"')$q$,'rejects invalid original extension');
select pg_temp.expect_failure($q$update public.contest_submissions set user_id='00000000-0000-4000-8000-000000000003'$q$,'cannot reassign submission');
select pg_temp.expect_failure($q$update public.contest_submissions set submitted_at='2000-01-01'$q$,'cannot forge submitted timestamp');
update public.contests set is_open=false;
select pg_temp.assert_true((select bool_and(is_open) from public.contests),'non-host cannot pause contest');
delete from storage.objects;
select pg_temp.assert_true((select count(*)=1 from storage.objects),'cannot delete a submitted file');
update storage.objects set metadata='{"size":999}';
select pg_temp.assert_true((select metadata->>'size'='123' from storage.objects),'cannot overwrite a submitted file');

-- Another participant cannot read responses or files, including by guessing their paths.
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=0 from public.contest_submissions),'participants cannot read others submissions');
select pg_temp.assert_true((select count(*)=0 from storage.objects),'participants cannot download others files');
select pg_temp.expect_failure($q$insert into storage.objects(bucket_id,name,metadata) values ('contest-submissions','10000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000001/forged.pptx','{"size":123}')$q$,'cannot upload as another participant');

-- A different host cannot read this contest's entries.
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select pg_temp.assert_true((select count(*)=0 from public.contest_submissions),'unrelated host cannot read entries');
select pg_temp.assert_true((select count(*)=0 from storage.objects),'unrelated host cannot read files');

-- The actual host can read entries and files, but cannot modify participant answers.
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)=1 from public.contest_submissions),'host reads entries');
select pg_temp.assert_true((select count(*)=1 from storage.objects),'host downloads submitted files');
update public.contest_submissions set participant_name='호스트가 변조';
select pg_temp.assert_true((select participant_name='수정한 참가자' from public.contest_submissions),'host cannot modify entries');
update public.contests set is_open=false;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_failure($q$update public.contest_submissions set participant_name='마감 후 수정'$q$,'paused contest rejects resubmission');
select pg_temp.expect_failure($q$insert into storage.objects(bucket_id,name,metadata) values ('contest-submissions','10000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000001/late.pptx','{"size":123}')$q$,'paused contest rejects upload');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
update public.contests set is_open=true,ends_at=clock_timestamp()+interval '1.1 seconds';
select pg_temp.assert_true((select ends_at between clock_timestamp() and clock_timestamp()+interval '2 seconds' from public.contests),'deadline retains sub-minute precision');
select pg_sleep(1.2);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_failure($q$update public.contest_submissions set participant_name='초 단위 마감 후 수정'$q$,'server deadline rejects resubmission');
select pg_temp.expect_failure($q$insert into storage.objects(bucket_id,name,metadata) values ('contest-submissions','10000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000001/late.pptx','{"size":123}')$q$,'server deadline rejects uploads');
select pg_temp.assert_true((select count(*)=1 from public.contest_submissions),'own submission readable after deadline');
reset role;
set local role anon;
select pg_temp.expect_failure($q$select * from public.contest_submissions$q$,'unauthenticated cannot read entries');
select pg_temp.expect_failure($q$select public.contest_server_time()$q$,'clock RPC requires authentication');
rollback;
\echo 'PASS: contest permissions, submission validation, extensions, uploads, resubmission and second-precision server deadline'
